import { isSegmentLabel } from './is-segment-label';
import { sanitizeLabelStackName } from './sanitize-label-stack-name';
export function stringifyLabelStackFully(labelStack) {
  return labelStack.map(function (l) {
    var name = sanitizeLabelStackName(l.name);
    if (isSegmentLabel(l)) {
      return "".concat(name, ":").concat(l.segmentId);
    }
    return name;
  }).join('/');
}